import fs from 'node:fs';
import path from 'node:path';
export function collect({ root, paths }) {
  return paths.flatMap((p) => [...fs.readFileSync(path.join(root, p), 'utf8').matchAll(/(PLANT|no-foo)/g)].map((m) => ({ rule: m[1] === 'PLANT' ? 'plant' : 'no-foo', path: p })));
}

